//! ♻️ Intrinsic history retirement returns every original read and its exact issuer before closing typed entries and bounded native backing.
use super::*;
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,FactoryAuthority,ArtifactOwnedValueRetirementFactory,FactoryOwnedRetirement,ErasedSnapshotRetirement};
use semio_framework_value::retained_clone::{RetainedCloneClose,retained_clone_grant_admits};
use semio_framework_value::retirement::{RetireOwned,RetirementCursor,RetirementStep};
use std::{mem::{ManuallyDrop,size_of},sync::Arc};
struct LedgerRetirement<T:RetireOwned>{ledger:ManuallyDrop<Option<ArtifactHistoryLedger<T>>>,payload:ManuallyDrop<Option<T>>,factory:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<T>>>>,ticket:ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,intrinsic:RetainedCloneClose,authority:Option<FactoryAuthority>,returned:Option<ArtifactHistoryReadKey>}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(||ValueError::literal(protocol::value::ValueRefusalKind::DepthLimit,"intrinsic history child depth overflow"))?;Ok(d)}
impl<T:RetireOwned> LedgerRetirement<T>{
 fn demand(&self,body:usize)->Result<RetirementDemand,ValueError>{
  if let Some(ticket)=self.ticket.as_ref(){return nested(semio_framework_value::factory_ticket_demands(ticket,body)?)}
  if !self.intrinsic.is_empty(){return nested(self.intrinsic.next_owner_demands::<T>(false,&None,body)?)}
  if let Some(authority)=self.authority.as_ref(){return if authority.terminal_is_empty(){Ok(header::<Option<FactoryAuthority>>())}else{nested(authority.demands(body)?)}}
  if self.payload.is_some(){return if self.factory.is_some(){nested(RetirementDemand{capacity_bytes:FactoryOwnedRetirement::<T>::constructor_capacity_bytes(),depth:1,..Default::default()})}else{self.intrinsic.next_owner_demands::<T>(true,&None,body)}}
  if let Some(key)=self.returned{if self.factory.is_some(){return Ok(header::<(T,ArtifactHistoryReadKey)>())}return nested(self.ledger.as_ref().unwrap().retained_read_return_demands(key,body)?)}
  if self.factory.is_some(){return Ok(header::<FactoryAuthority>())}
  if let Some(ledger)=self.ledger.as_ref(){if ledger.next_retained_read_key().is_some(){return Ok(header::<Option<ArtifactHistoryReadKey>>())}if !ledger.is_empty(){return Ok(header::<T>())}if !ledger.terminal_is_empty(){return Err(ValueError::literal(protocol::value::ValueRefusalKind::OwnershipLimit,"intrinsic history retirement requires its original group decision to settle"))}if ledger.retained_terminal_slot_count()>0{return Ok(header::<Option<Arc<ArtifactGroupVisibility>>>())}return Ok(RetirementDemand{release_bytes:ledger.next_empty_page_release_byte_demand()?,depth:1,..Default::default()})}Ok(Default::default())
 }
 fn empty(&self)->bool{self.ledger.is_none()&&self.payload.is_none()&&self.factory.is_none()&&self.ticket.is_none()&&self.intrinsic.is_empty()&&self.authority.is_none()&&self.returned.is_none()}
 fn step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()};let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};
  if self.ticket.is_some(){return semio_framework_value::close_factory_ticket(&mut self.ticket,child).map(|step|RetainedCloneStep::Progress(step.progress()))}
  if !self.intrinsic.is_empty(){return self.intrinsic.step_granted(child).map(|step|RetainedCloneStep::Progress(step.progress()))}
  if let Some(authority)=self.authority.as_mut(){if !authority.terminal_is_empty(){return authority.step(child).map(|step|RetainedCloneStep::Progress(step.progress()))}self.authority=None;return Ok(RetainedCloneStep::Progress(p))}
  if self.payload.is_some(){if let Some(factory)=self.factory.as_ref(){let Some((ticket,p))=FactoryOwnedRetirement::<T>::admit_original(&mut self.payload,factory,child)?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.ticket=Some(ticket);return Ok(RetainedCloneStep::Progress(p))}return Ok(self.intrinsic.begin_granted(&mut self.payload,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}
  if let Some(key)=self.returned{if self.factory.is_none(){return self.ledger.as_mut().unwrap().return_retained_read(key,&mut self.factory,child).map(|step|RetainedCloneStep::Progress(step.progress()))}*self.payload=Some(self.ledger.as_mut().unwrap().remove_key(key.key).map_err(|_|ValueError::literal(protocol::value::ValueRefusalKind::InvariantViolated,"returned original history slot changed"))?);self.returned=None;return Ok(RetainedCloneStep::Progress(p))}
  if let Some(factory)=self.factory.take(){self.authority=Some(FactoryAuthority::new(factory));return Ok(RetainedCloneStep::Progress(p))}
  if let Some(ledger)=self.ledger.as_mut(){if let Some(key)=ledger.next_retained_read_key(){self.returned=Some(key);return Ok(RetainedCloneStep::Progress(p))}if let Some(value)=ledger.pop(){*self.payload=Some(value);return Ok(RetainedCloneStep::Progress(p))}if ledger.retained_terminal_slot_count()>0{let(view,mut receipt)=ledger.retire_terminal_slot(g)?;receipt.copied_bytes=d.copy_bytes;if let Some(view)=view{self.authority=Some(FactoryAuthority::new(view))}return Ok(RetainedCloneStep::Progress(receipt))}if !ledger.backing_is_empty(){return ledger.release_empty_page(g).map(|step|RetainedCloneStep::Progress(step.progress()))}self.ledger.take();return Ok(RetainedCloneStep::Progress(p))}Ok(RetainedCloneStep::Complete(Default::default()))
 }
}
impl<T:RetireOwned> RetireOwned for ArtifactHistoryLedger<T>{fn retirement(self)->Box<dyn RetirementCursor>{Box::new(LedgerRetirement{ledger:ManuallyDrop::new(Some(self)),payload:ManuallyDrop::new(None),factory:ManuallyDrop::new(None),ticket:ManuallyDrop::new(None),intrinsic:Default::default(),authority:None,returned:None})}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<LedgerRetirement<T>>())}fn controlled_retirement_supported()->bool{T::controlled_retirement_supported()}}
impl<T:RetireOwned> RetirementCursor for LedgerRetirement<T>{fn next_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{self.demand(b)}fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{match self.step(g){Ok(RetainedCloneStep::Complete(p))if p==Default::default()=>RetirementStep::Complete,Ok(step)=>RetirementStep::Progress(step.progress()),Err(e)=>RetirementStep::Failure(e)}}fn terminal_is_empty(&self)->bool{self.empty()}fn terminal_release_bytes(&self)->Option<usize>{self.empty().then_some(size_of::<Self>())}}
impl<T:RetireOwned> Drop for LedgerRetirement<T>{fn drop(&mut self){assert!(self.empty()||std::thread::panicking(),"intrinsic history retirement retains original slots and issuers until funded terminal closure");if self.empty(){unsafe{ManuallyDrop::drop(&mut self.ledger);ManuallyDrop::drop(&mut self.payload);ManuallyDrop::drop(&mut self.factory);ManuallyDrop::drop(&mut self.ticket);}}}}

#[cfg(test)]
mod tests{
 use super::*;
 use semio_framework_value::retirement::controlled::ControlledRetirement;
 fn observe<T>(call:impl FnOnce()->T)->(T,usize,usize){let(value,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(call);(value,h.requested_bytes,h.released_bytes)}
 static ORIGINAL:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
 #[derive(semio_framework_value::FactoryPayloadRetirement)]
 struct Issuer;
 impl ArtifactOwnedValueRetirementFactory<String> for Issuer{fn retirement_birth_bytes(&self,_:&String)->usize{semio_framework_value::owned_retirement_birth_bytes::<String>()}fn retire_owned(&self,original:String,g:RetainedCloneGrant)->Result<(Box<dyn ErasedSnapshotRetirement>,RetainedCloneProgress),(ValueError,String)>{ORIGINAL.store(original.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed);semio_framework_value::admit_owned_retirement(original,g)}}
 fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096,"original history body {:?}",d);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
 #[test]
 fn original_intrinsic_ledger_returns_same_read_issuer_and_waits_for_owning_projection(){for prefix in [0,1,2]{ORIGINAL.store(0,std::sync::atomic::Ordering::Relaxed);let mut ledger=ArtifactHistoryLedger::empty();let d=ledger.initial_page_birth_demand().unwrap();let(p,a,r)=observe(||ledger.admit_initial_page(grant(d)).unwrap());assert_eq!((a,r),(p.retained_capacity_bytes,p.released_bytes));let original="actual native α".repeat(1024);let pointer=original.as_ptr()as usize;let key=ledger.try_push(original).ok().unwrap();let key=ledger.retained_read_key(key).unwrap();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(Issuer);for _ in 0..prefix{let d=ledger.retained_read_demands(key).unwrap();ledger.advance_retained_read(key,&factory,grant(d)).unwrap();}let mut projection=if prefix==2{let d=semio_framework_value::RetainedOwnedProjection::<String>::constructor_demand();Some(ledger.retain_read(key,grant(d)).unwrap().0)}else{None};let mut close=ControlledRetirement::new(ledger).ok().unwrap();for turn in 0..10000{if turn==5{if let Some(read)=projection.as_mut(){while !read.terminal_is_empty(){let d=read.close_demand(4096).unwrap();let(step,a,r)=observe(||read.close_step(grant(d)).unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}projection=None;}if close.terminal_is_empty(){break}let d=close.next_demand(4096).unwrap();let(step,a,r)=observe(||close.step(grant(d)).unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));if projection.is_some(){assert_eq!(ORIGINAL.load(std::sync::atomic::Ordering::Relaxed),0);}assert!(turn<9999);}assert!(close.terminal_is_empty());assert_eq!(ORIGINAL.load(std::sync::atomic::Ordering::Relaxed),if prefix==0{0}else{pointer});}}
}
